local HalberdSmith = {}
local PRODUCTS = {
    simple_iron_halberd = { name = "Preprost železni helebarda", ironCost = 3, woodCost = 2, time = 5, cost = 150, attack = 32, happiness = 1, description = "Preprost železni helebarda za vojake." },
    steel_axe_halberd = { name = "Jeklenosekična helebarda", ironCost = 2, steelCost = 2, woodCost = 2, time = 8, cost = 380, attack = 48, happiness = 1, prestige = 3, description = "Jeklenosekična helebarda za viteze." },
    silver_inlaid_halberd = { name = "Srebrnovložena helebarda", ironCost = 2, steelCost = 2, silverCost = 1, woodCost = 2, time = 11, cost = 820, attack = 62, happiness = 2, prestige = 8, description = "Srebrnovložena helebarda za plemiške viteze." },
    gold_trimmed_halberd = { name = "Zlatookrasna helebarda", ironCost = 2, steelCost = 2, goldCost = 1, silverCost = 1, woodCost = 2, time = 15, cost = 1800, attack = 76, happiness = 3, prestige = 18, description = "Zlatookrasna helebarda za visoke plemiče." },
    jewel_pommel_halberd = { name = "Draguljnogrbi helebarda", ironCost = 2, steelCost = 2, goldCost = 1, silverCost = 1, woodCost = 2, jewelCost = 1, time = 19, cost = 3800, attack = 88, happiness = 5, prestige = 32, description = "Helebarda z draguljnim grbičem za visoko plemstvo." },
    royal_grand_halberd = { name = "Kraljevski veliki helebarda", ironCost = 3, steelCost = 3, goldCost = 2, silverCost = 2, woodCost = 3, jewelCost = 2, pearlCost = 2, time = 26, cost = 7500, attack = 98, happiness = 12, prestige = 62, description = "Velika kraljevska helebarda z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    halberd_workshop = { name = "Helebardska delavnica", cost = { gold = 260, wood = 140, stone = 120, iron = 6 }, upkeep = 6, qualityBonus = 5 },
    polearm_loft = { name = "Sulicepodstrešje", cost = { gold = 1000, wood = 280, stone = 280, steel = 6, silver = 6 }, upkeep = 24, qualityBonus = 18 },
    master_polearm_atelier = { name = "Mojstrski sulični atelje", cost = { gold = 2800, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 65, qualityBonus = 30 },
    royal_halberd_palace = { name = "Kraljevska helebardska palača", cost = { gold = 12000, wood = 600, stone = 800, gold = 80, jewel = 18 }, upkeep = 240, qualityBonus = 55, prestigeBonus = 50 },
}
HalberdSmith.ironStock = 16; HalberdSmith.steelStock = 10; HalberdSmith.woodStock = 14; HalberdSmith.silverStock = 6; HalberdSmith.goldStock = 6; HalberdSmith.jewelStock = 4; HalberdSmith.pearlStock = 4
HalberdSmith.productStock = {}; HalberdSmith.buildings = {}; HalberdSmith.maker = nil; HalberdSmith.activeMaking = {}; HalberdSmith.totalProducts = 0; HalberdSmith.dayTimer = 0
function HalberdSmith.init() HalberdSmith.ironStock=16; HalberdSmith.steelStock=10; HalberdSmith.woodStock=14; HalberdSmith.silverStock=6; HalberdSmith.goldStock=6; HalberdSmith.jewelStock=4; HalberdSmith.pearlStock=4; HalberdSmith.productStock={}; HalberdSmith.buildings={}; HalberdSmith.maker=nil; HalberdSmith.activeMaking={}; HalberdSmith.totalProducts=0; HalberdSmith.dayTimer=0; print("[HalberdSmith] Royal Halberd Smith System initialized (6 products, 4 buildings)") end
function HalberdSmith.hireMaker(n,s) s=s or math.random(55,90); local c=540+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; HalberdSmith.maker={name=n or ("Helebardar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Helebardar najet: %s (spretnost: %d)",HalberdSmith.maker.name,s),"success") end; return true end
function HalberdSmith.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function HalberdSmith.build(id) local ok,e=HalberdSmith.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(HalberdSmith.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function HalberdSmith.getQualityBonus() local b=0; for _,bd in ipairs(HalberdSmith.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function HalberdSmith.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and HalberdSmith.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.steelCost and HalberdSmith.steelStock<(d.steelCost or 0) then return false,"Premalo jekla" end; if d.woodCost and HalberdSmith.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.silverCost and HalberdSmith.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and HalberdSmith.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and HalberdSmith.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and HalberdSmith.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #HalberdSmith.buildings==0 then return false,"Potrebna helebardska delavnica" end; if not HalberdSmith.maker then return false,"Potreben helebardar" end; return true end
function HalberdSmith.make(pt,qty) qty=qty or 1; local ok,e=HalberdSmith.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then HalberdSmith.ironStock=HalberdSmith.ironStock-d.ironCost*qty end; if d.steelCost then HalberdSmith.steelStock=HalberdSmith.steelStock-d.steelCost*qty end; if d.woodCost then HalberdSmith.woodStock=HalberdSmith.woodStock-d.woodCost*qty end; if d.silverCost then HalberdSmith.silverStock=HalberdSmith.silverStock-d.silverCost*qty end; if d.goldCost then HalberdSmith.goldStock=HalberdSmith.goldStock-d.goldCost*qty end; if d.jewelCost then HalberdSmith.jewelStock=HalberdSmith.jewelStock-d.jewelCost*qty end; if d.pearlCost then HalberdSmith.pearlStock=HalberdSmith.pearlStock-d.pearlCost*qty end; local t=d.time; if HalberdSmith.maker then t=math.max(1,t-math.floor(HalberdSmith.maker.skill/12)) end; table.insert(HalberdSmith.activeMaking,{id="halberd_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,attack=d.attack or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kovanje: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function HalberdSmith.completeMaking(m) local q=1.0+(HalberdSmith.getQualityBonus()/100); if HalberdSmith.maker then q=q+(HalberdSmith.maker.skill/140) end; q=math.min(2.5,q); HalberdSmith.productStock[m.productType]=(HalberdSmith.productStock[m.productType] or 0)+m.quantity; HalberdSmith.totalProducts=HalberdSmith.totalProducts+m.quantity; if m.attack>0 and _G.state then _G.state.attack=(_G.state.attack or 0)+m.attack end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if HalberdSmith.maker then HalberdSmith.maker.itemsMade=HalberdSmith.maker.itemsMade+m.quantity; if math.random()<0.25 then HalberdSmith.maker.skill=math.min(100,HalberdSmith.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Helebarda izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"halberd.completed",{productName=m.productName,attack=m.attack,prestige=m.prestige,happiness=m.happiness}) end end
function HalberdSmith.update(dt) if not _G.state then return end; HalberdSmith.dayTimer=HalberdSmith.dayTimer+dt; if HalberdSmith.dayTimer>=30 then HalberdSmith.dayTimer=0; for i=#HalberdSmith.activeMaking,1,-1 do local m=HalberdSmith.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then HalberdSmith.completeMaking(m); table.remove(HalberdSmith.activeMaking,i) end end; local tu=0; for _,bd in ipairs(HalberdSmith.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if HalberdSmith.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function HalberdSmith.getStats() return {ironStock=HalberdSmith.ironStock,steelStock=HalberdSmith.steelStock,woodStock=HalberdSmith.woodStock,silverStock=HalberdSmith.silverStock,goldStock=HalberdSmith.goldStock,jewelStock=HalberdSmith.jewelStock,pearlStock=HalberdSmith.pearlStock,productStock=HalberdSmith.productStock,numBuildings=#HalberdSmith.buildings,hasMaker=HalberdSmith.maker~=nil,makerName=HalberdSmith.maker and HalberdSmith.maker.name or "—",makerSkill=HalberdSmith.maker and HalberdSmith.maker.skill or 0,activeMaking=#HalberdSmith.activeMaking,totalProducts=HalberdSmith.totalProducts} end
return HalberdSmith
